// Chapter 04 of the book — converted from the HTML edition; generated file.

export const n = 4;
export const num = "04";
export const title = "اولین مخزن — init تا log";
export const label = "فصل ۴ · اولین مخزن";
export const part = 0;
export const html = "<p class=\"lead\">در این فصل یک پوشه را به مخزن Git تبدیل می‌کنی، دو کامیت با پیام روشن می‌نویسی، و با <code>log</code> می‌بینی تاریخچه دقیقاً چه شکلی شده.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>مخزن را از صفر با <code>git init</code> یا از VS Code بسازی</li>\n<li>پیام کامیت خوب بنویسی</li>\n<li><code>log</code> را با گراف بخوانی</li>\n<li>تفاوت <code>--allow-empty</code> و کامیت واقعی را بدانی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">🚀 ساخت مخزن</span></span></h2>\n<h3><span class=\"hx\"><span class=\"hx-t\">روش ۱ — ترمینال (پایه)</span></span></h3>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">init تمیز</span></div><pre>mkdir<span style=\"color: #F8F8F2\"> </span>git-lab<span style=\"color: #F8F8F2\"> </span><span style=\"color: #FF4689\">&amp;&amp;</span><span style=\"color: #F8F8F2\"> cd </span>git-lab\ngit<span style=\"color: #F8F8F2\"> </span>init<span style=\"color: #F8F8F2\"> </span>-b<span style=\"color: #F8F8F2\"> </span>main\n<span style=\"color: #959077\"># Initialized empty Git repository in .../.git/</span>\n\n<span style=\"color: #F8F8F2\">echo </span><span style=\"color: #E6DB74\">&quot;# Git Lab&quot;</span><span style=\"color: #F8F8F2\"> </span>&gt;<span style=\"color: #F8F8F2\"> </span>README.md\ngit<span style=\"color: #F8F8F2\"> </span>add<span style=\"color: #F8F8F2\"> </span>README.md\ngit<span style=\"color: #F8F8F2\"> </span>status\ngit<span style=\"color: #F8F8F2\"> </span>commit<span style=\"color: #F8F8F2\"> </span>-m<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;chore: bootstrap repository&quot;</span>\n</pre></div>\n<p>پرچم <code>-b main</code> شاخهٔ پیش‌فرض را <code>master</code> نمی‌گذارد. اگر فراموش کردی: <code>git config --global init.defaultBranch main</code>.</p>\n<h3><span class=\"hx\"><span class=\"hx-t\">روش ۲ — VS Code (توصیهٔ این کتاب)</span></span></h3>\n<ol>\n<li>پوشه را با <em>File → Open Folder</em> باز کن</li>\n<li>نوار کناری آیکون Git را بزن (<code>Ctrl+Shift+G</code>)</li>\n<li>دکمهٔ <strong>Initialize Repository</strong></li>\n<li>فایل بساز، در Changes ظاهر می‌شود</li>\n<li>پیام را بنویس و <code>Ctrl+Enter</code></li>\n</ol>\n<p>اگر پنل خالی دیدی و دکمهٔ Initialize نبود، یا پوشه Git ندارد یا Git در PATH نیست.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">✍️ پیام کامیت — قرارداد این کتاب</span></span></h2>\n<p class=\"keep-next\">از <strong>Conventional Commits</strong> استفاده می‌کنیم (فصل ۲۲ عمیق می‌شود):</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">قالب</span></div><pre>type(scope): summary\n\nبدنهٔ اختیاری — چرا، نه چه.\n</pre></div>\n<p class=\"keep-next\">انواع رایج: <code>feat</code>، <code>fix</code>، <code>docs</code>، <code>chore</code>، <code>refactor</code>، <code>test</code>، <code>ci</code>.</p>\n<div class=\"cols\">\n<div class=\"col good\"><div class=\"col-title\">خوب</div>\n<p><code>feat(auth): add refresh-token rotation</code></p>\n<p>چرا: نوع + محدوده + فعل امری + نتیجه.</p>\n</div>\n<div class=\"col bad\"><div class=\"col-title\">بد</div>\n<p><code>update</code> یا <code>fix bug</code> یا <code>asdf</code></p>\n<p>تاریخچهٔ بی‌معنی، <code>git log</code> را به زباله‌دان تبدیل می‌کند.</p>\n</div>\n</div>\n<p>در VS Code پیام را در جعبهٔ بالا می‌نویسی. <code>Ctrl+Enter</code> کامیت می‌کند. اگر <em>Smart Commit</em> روشن باشد و چیزی stage نشده باشد، همه چیز را قورت می‌دهد — در فصل ۲ آن را خاموش کردیم.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">📜 خواندن تاریخچه</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">log به سبک Senior</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>log<span style=\"color: #F8F8F2\"> </span>--oneline<span style=\"color: #F8F8F2\"> </span>--decorate<span style=\"color: #F8F8F2\"> </span>--graph<span style=\"color: #F8F8F2\"> </span>--all\ngit<span style=\"color: #F8F8F2\"> </span>log<span style=\"color: #F8F8F2\"> </span>-1<span style=\"color: #F8F8F2\"> </span>-p<span style=\"color: #F8F8F2\">                 </span><span style=\"color: #959077\"># آخرین کامیت + diff</span>\ngit<span style=\"color: #F8F8F2\"> </span>show<span style=\"color: #F8F8F2\"> </span>HEAD<span style=\"color: #F8F8F2\">                 </span><span style=\"color: #959077\"># معادل بالا</span>\ngit<span style=\"color: #F8F8F2\"> </span>log<span style=\"color: #F8F8F2\"> </span>--author<span style=\"color: #FF4689\">=</span><span style=\"color: #E6DB74\">&quot;rezaian&quot;</span><span style=\"color: #F8F8F2\"> </span>--since<span style=\"color: #FF4689\">=</span><span style=\"color: #E6DB74\">&quot;2 weeks ago&quot;</span>\ngit<span style=\"color: #F8F8F2\"> </span>shortlog<span style=\"color: #F8F8F2\"> </span>-sn<span style=\"color: #F8F8F2\">              </span><span style=\"color: #959077\"># چه کسی چقدر کامیت کرده</span>\n</pre></div>\n<p class=\"keep-next\">در VS Code:</p>\n<ul>\n<li><em>Timeline</em> زیر فایل → تاریخچهٔ همان فایل</li>\n<li><em>Git Graph</em> / GitLens → کل DAG</li>\n<li>کلیک روی کامیت در Source Control → جزئیات</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">🔬 داخل <code>.git</code> چه خبر است؟</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">تور سریع</span></div><pre>ls<span style=\"color: #F8F8F2\"> </span>.git\n<span style=\"color: #959077\"># HEAD  config  description  hooks  info  objects  refs</span>\n\ncat<span style=\"color: #F8F8F2\"> </span>.git/HEAD<span style=\"color: #F8F8F2\">          </span><span style=\"color: #959077\"># ref: refs/heads/main</span>\ncat<span style=\"color: #F8F8F2\"> </span>.git/refs/heads/main\n<span style=\"color: #959077\"># 9f3a1c...  ← هش کامیت فعلی</span>\n</pre></div>\n<p>هنوز لازم نیست packfile را بفهمی (فصل ۳۰). فقط بدان: <strong>هر چیز ماندگار اینجاست</strong>؛ پاک کردن <code>.git</code> یعنی قتل تاریخچه.</p>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">amend برای ۵ دقیقهٔ اول</div>\n<p>اگر همین الان پیام را غلط نوشتی و هنوز push نکرده‌ای:</p>\n<p><code>git commit --amend -m &quot;docs: fix readme title&quot;</code></p>\n<p>در VS Code: تیک <em>Amend</em> کنار دکمهٔ Commit (منوی کشویی ✓).</p>\n</div>\n<div class=\"callout callout-warn\"><div class=\"callout-title\">هرگز amend بعد از push</div>\n<p><code>--amend</code> هش را عوض می‌کند. اگر دیگران آن کامیت را گرفته‌اند، تاریخچه دوپاره می‌شود. قانون: فقط کامیت محلیِ pushنشده.</p>\n</div>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — <code>git init</code> چه می‌سازد؟</strong> پوشهٔ <code>.git</code> با HEAD، objects، refs و config.</p>\n<p><strong>Mid — چرا پیام امری می‌نویسیم؟</strong> کامیت را مثل وصله بخوان: «این وصله refresh-token را اضافه می‌کند.» نه «اضافه کردم.»</p>\n<p><strong>Senior — تفاوت <code>git log -p</code> و <code>git show</code>؟</strong> <code>show</code> یک شیء را نمایش می‌دهد؛ <code>log -p</code> پیمایش تاریخچه با diff هر کامیت است.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>مخزن با شاخهٔ <code>main</code> ساخته‌ای</li>\n<li>حداقل دو کامیت Conventional داری</li>\n<li><code>git lg</code> (یا alias) گراف را نشان می‌دهد</li>\n<li>می‌دانی <code>.git</code> قلب مخزن است</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> اشیای Git — blob، tree، commit و جادوی hash.</p></div>";
export default { n, num, title, label, part, html };
